def calculate_scores(ingested_data, matrix_config):
    latency = ingested_data.get('execution_latency_ms', 500)
    error_rate = ingested_data.get('error_rate_percentage', 0)
    manual_rating = ingested_data.get('input_manager_score', 5) * 10

    if latency < 200:
        efficiency_score = 100
    elif latency < 1000:
        efficiency_score = 80
    else:
        efficiency_score = 40

    quality_score = max(0, min(100, manual_rating - (error_rate * 2)))

    w_eff = matrix_config['DIM_CORE_EFFICIENCY']['weight']
    w_qua = matrix_config['DIM_QUALITY_ACCURACY']['weight']

    final_composite_score = (efficiency_score * w_eff) + (quality_score * w_qua)

    return {
        'compositeScore': round(final_composite_score, 2),
        'breakdown': {
            'DIM_CORE_EFFICIENCY': efficiency_score,
            'DIM_QUALITY_ACCURACY': quality_score
        }
    }
